// Copies the tesseract.js worker and WebAssembly cores into public/tesseract/, and fetches the English language
// data once (tessdata_fast, pinned tag) into public/tesseract/lang/eng.traineddata.gz. Manifest V3 forbids remote
// code, so the worker and the cores must ship inside the extension; the language data ships too so that reading
// a photo on this device makes no network request at all. Output is gitignored and regenerated by `npm run build`.
import { copyFileSync, existsSync, mkdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { gzipSync } from 'node:zlib';

const require = createRequire(import.meta.url);
const jsRoot = dirname(require.resolve('tesseract.js/package.json'));
const coreRoot = dirname(require.resolve('tesseract.js-core/package.json'));
const out = join(process.cwd(), 'public', 'tesseract');
mkdirSync(join(out, 'lang'), { recursive: true });

// The worker (which importScripts the core) and two LSTM-only cores as glue + wasm pairs: relaxed SIMD for
// Chrome 114 and later, plain SIMD as the fallback. lib/ocr.ts picks one with WebAssembly.validate and names the
// glue file directly, so the worker never reaches for the CDN. The glue finds its .wasm next to itself.
copyFileSync(join(jsRoot, 'dist/worker.min.js'), join(out, 'worker.min.js'));
for (const name of ['tesseract-core-relaxedsimd-lstm', 'tesseract-core-simd-lstm']) {
  copyFileSync(join(coreRoot, `${name}.js`), join(out, `${name}.js`));
  copyFileSync(join(coreRoot, `${name}.wasm`), join(out, `${name}.wasm`));
}
for (const stale of ['tesseract-core-lstm.wasm.js', 'tesseract-core-lstm.wasm', 'tesseract-core-relaxedsimd-lstm.wasm.js', 'tesseract-core-simd-lstm.wasm.js']) rmSync(join(out, stale), { force: true });
const jsVersion = JSON.parse(readFileSync(join(jsRoot, 'package.json'), 'utf8')).version;
writeFileSync(join(out, 'VERSION'), `tesseract.js ${jsVersion}\n`);

// English, from the tesseract project's own fast models, at a fixed tag so the build is reproducible.
const LANG_URL = 'https://github.com/tesseract-ocr/tessdata_fast/raw/4.1.0/eng.traineddata';
const MIN_BYTES = 3_500_000; // the real file is about 4.1 MB; anything smaller is an error page
const target = join(out, 'lang', 'eng.traineddata.gz');
if (existsSync(target) && statSync(target).size > 1_000_000) {
  console.log(`gen-tesseract: worker and cores copied; ${target} already present`);
} else {
  process.stdout.write('gen-tesseract: fetching English language data (about 4 MB, once)… ');
  const res = await fetch(LANG_URL, { redirect: 'follow' });
  if (!res.ok) throw new Error(`gen-tesseract: ${LANG_URL} returned ${res.status}`);
  const raw = Buffer.from(await res.arrayBuffer());
  if (raw.length < MIN_BYTES) throw new Error(`gen-tesseract: language file is only ${raw.length} bytes; expected about 4 MB`);
  writeFileSync(target, gzipSync(raw, { level: 9 }));
  console.log(`${(statSync(target).size / 1e6).toFixed(1)} MB gzipped`);
}
